begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(14);
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.v6_revision_memberships'::regclass),'membership table forces RLS');
select ok(not has_table_privilege('authenticated','private.v6_revision_memberships','insert'),'athlete cannot create membership');
select ok(not has_table_privilege('service_role','private.v6_revision_memberships','insert'),'service cannot bypass guarded membership writer');
select ok(not has_table_privilege('anon','private.v6_revision_memberships','select'),'anonymous membership read denied');
select ok(not has_table_privilege('authenticated','private.v6_revision_occurrences','select'),'private mapping view not directly readable');
select ok(not has_function_privilege('anon','private.v6_revision_workouts(uuid)','execute'),'anonymous row helper denied');
select ok(has_function_privilege('authenticated','private.v6_revision_workouts(uuid)','execute'),'owner-scoped helper supports existing invoker reads');
select ok(not has_function_privilege('authenticated','private.v6_active_workout_member(uuid,uuid)','execute'),'internal active resolver remains private');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"a6000000-0000-0000-0000-000000000006"}',true);
select throws_ok($$select * from private.v6_revision_workouts('b6000000-0000-0000-0000-000000000006')$$,'42501','workout owner authorization required','foreign owner cannot use internal projection');
reset role;
select is((select count(*)::integer from pg_constraint where conrelid='private.v6_revision_memberships'::regclass and contype='f'),5,'origin, parent, revision and dual owners all retain foreign keys');
select ok((select count(*)=2 from pg_trigger where tgrelid='private.v6_revision_memberships'::regclass and tgname in ('v6_membership_immutable','v6_membership_scope')),'membership scope and immutability enforced');
select ok(exists(select 1 from pg_trigger where tgrelid='private.v6_occurrence_snapshots'::regclass and tgname='v6_native_membership_scope'),'native and carried identities cannot overlap in either insert order');
select is((select count(*)::integer from private.v6_source_revisions where activation <> 'INACTIVE'),0,'catalog still inactive');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='private.v6_revision_workouts(uuid)'::regprocedure),'internal helper has fixed search path');
select * from finish();
rollback;
